'use strict';
(()=>{
const grid=$('#album-grid'),status=$('#catalog-status'),cache=new Map(),knownAlbums=new Map(),knownArtists=new Map();
let albums=[],artists=[],saved=[],onlySaved=false,mode='albums',searchVersion=0,detailVersion=0,callbackId=0,searchTimer;
try{const data=JSON.parse(localStorage.getItem('mono-albums')||'[]');if(Array.isArray(data))saved=data.filter(a=>a&&Number.isSafeInteger(a.collectionId)).slice(0,200)}catch{}
function safeURL(value,art=false){try{const u=new URL(value);return u.protocol==='https:'&&(art?u.hostname.endsWith('.mzstatic.com'):['music.apple.com','itunes.apple.com'].includes(u.hostname))?u.href:''}catch{return ''}}
const artwork=a=>safeURL(a.artworkUrl100,true).replace(/100x100bb/,'400x400bb');
function cover(a,large=false){const src=artwork(a);return `<div class="album-cover ${large?'large':''}"><span aria-hidden="true">♫</span>${src?`<img src="${escapeHTML(src)}" alt="${escapeHTML(a.collectionName)} album cover" loading="${large?'eager':'lazy'}" decoding="async">`:''}</div>`}
function request(path,params){const key=path+JSON.stringify(params);if(cache.has(key))return Promise.resolve(cache.get(key));return new Promise((resolve,reject)=>{const cb='monoCatalogCallback'+(++callbackId),script=document.createElement('script');let timer;function cleanup(){clearTimeout(timer);script.remove();delete window[cb]}window[cb]=data=>{cleanup();if(!Array.isArray(data?.results))return reject(new Error('Invalid catalog response'));cache.set(key,data.results);if(cache.size>30)cache.delete(cache.keys().next().value);resolve(data.results)};script.onerror=()=>{cleanup();reject(new Error('Catalog unavailable'))};script.src='https://itunes.apple.com/'+path+'?'+new URLSearchParams({...params,country:'us',callback:cb});timer=setTimeout(()=>{cleanup();reject(new Error('Catalog timed out'))},12000);document.head.append(script)})}
function remember(items){for(const a of items)knownAlbums.set(a.collectionId,a);while(knownAlbums.size>500)knownAlbums.delete(knownAlbums.keys().next().value)}
function images(root){root.querySelectorAll('.album-cover img').forEach(img=>img.onerror=()=>img.remove())}
function albumCard(a){return `<button class="album-card" data-album="${a.collectionId}" aria-label="View ${escapeHTML(a.collectionName)} by ${escapeHTML(a.artistName)}">${cover(a)}<b>${escapeHTML(a.collectionName)}</b><span>${escapeHTML(a.artistName)}</span><small>${escapeHTML((a.releaseDate||'').slice(0,4))} <i>•</i> ${a.trackCount===1?'Single':'Album'}</small></button>`}
function artistCard(a){return `<button class="album-card artist-card" data-artist-id="${a.artistId}" aria-label="View artist ${escapeHTML(a.artistName)}"><div class="artist-avatar">${escapeHTML(a.artistName.slice(0,1).toUpperCase())}</div><b>${escapeHTML(a.artistName)}</b><span>${escapeHTML(a.primaryGenreName||'Artist')}</span><small>Artist profile ↗</small></button>`}
function renderAlbums(){const list=onlySaved?saved:albums;$('#saved-albums').setAttribute('aria-pressed',onlySaved);$('#saved-albums').textContent=onlySaved?'All albums':`Saved albums${saved.length?' · '+saved.length:''}`;grid.innerHTML=mode==='artists'&&!onlySaved?artists.map(artistCard).join(''):list.map(albumCard).join('');images(grid);if(onlySaved)status.textContent=saved.length?`${saved.length} saved album${saved.length===1?'':'s'} · stored on this device`:'Your record shelf is waiting. Open an album and save it here.'}
function setMode(value){mode=value;onlySaved=false;$('#catalog-albums').setAttribute('aria-pressed',mode==='albums');$('#catalog-artists').setAttribute('aria-pressed',mode==='artists');$('#album-heading').textContent=mode==='artists'?'Artists to get to know':'Albums to spend time with';$('#catalog-query').placeholder=mode==='artists'?'Search an artist':'Search albums or artists';$('#catalog-submit').textContent=mode==='artists'?'Search artists':'Search albums';searchAlbums($('#catalog-query').value||'Daft Punk')}
async function searchAlbums(term){term=term.trim().slice(0,150);if(!term)return;const version=++searchVersion,currentMode=mode;onlySaved=false;$('#catalog-query').value=term;status.textContent=`Finding ${mode} for “${term}”…`;grid.setAttribute('aria-busy','true');try{const rows=await request('search',{term,media:'music',entity:mode==='artists'?'musicArtist':'album',...(mode==='artists'?{attribute:'artistTerm'}:{}),limit:'24'});if(version!==searchVersion)return;if(currentMode==='artists'){artists=rows.filter(a=>Number.isSafeInteger(a.artistId)&&a.artistName);artists.forEach(a=>knownArtists.set(a.artistId,a))}else{albums=rows.filter(a=>a.collectionType==='Album'&&Number.isSafeInteger(a.collectionId));remember(albums)}renderAlbums();const count=currentMode==='artists'?artists.length:albums.length;status.textContent=count?`${count} ${currentMode} for “${term}” · select one to explore`:`No ${currentMode} found for “${term}”. Try another name.`}catch{if(version!==searchVersion)return;status.innerHTML='The catalog is unavailable right now. <button id="catalog-retry">Try again ↗</button> or browse your saved albums.';$('#catalog-retry').onclick=()=>searchAlbums(term)}finally{if(version===searchVersion)grid.removeAttribute('aria-busy')}}
function toTrack(song,album={}){return {id:String(song.trackId),title:song.trackName,artist:song.artistName||album.artistName,artistId:song.artistId||album.artistId,album:song.collectionName||album.collectionName,albumId:song.collectionId||album.collectionId,artwork:artwork(song)||artwork(album),genre:song.primaryGenreName||album.primaryGenreName||'',duration:song.trackTimeMillis/1000}}
function songRow(t){return `<div class="catalog-track"><span>${Number(t.trackNumber)||'–'}</span><div><b>${escapeHTML(t.trackName)}</b><small>${escapeHTML(t.artistName)}</small></div><span class="track-duration">${time((Number(t.trackTimeMillis)||0)/1000)}</span><button class="album-track-play" data-play-song="${t.trackId}" aria-label="Play ${escapeHTML(t.trackName)} in Oktawka"><span class="material-symbols-rounded" aria-hidden="true">play_arrow</span></button></div>`}
function bindSongs(root,songs,album={}){root.querySelectorAll('[data-play-song]').forEach(button=>button.onclick=()=>{const song=songs.find(t=>String(t.trackId)===button.dataset.playSong);if(song){if(window.OktawkaFlow)window.OktawkaFlow.playAlbum(songs.map(t=>toTrack(t,album)),songs.indexOf(song));else window.monoPlayCatalogTrack?.(toTrack(song,album))}})}
function storeSaved(){try{localStorage.setItem('mono-albums',JSON.stringify(saved))}catch{toast('Device storage is unavailable. This save lasts for this session.')}}
async function openAlbum(id){const a=knownAlbums.get(id)||[...albums,...saved].find(a=>a.collectionId===id);if(!a)return;const version=++detailVersion;modal(`<div class="album-detail">${cover(a,true)}<div class="eyebrow">ALBUM · ${escapeHTML((a.releaseDate||'').slice(0,4))}</div><h2>${escapeHTML(a.collectionName)}</h2><p class="album-artist"><button class="artist-inline" id="album-artist-link">${escapeHTML(a.artistName)}</button> · ${Number(a.trackCount)||0} tracks</p><div class="album-actions"><button class="primary" id="album-find-sources"><span class="material-symbols-rounded" aria-hidden="true">play_arrow</span>Play album</button><button class="secondary" id="save-album"></button>${safeURL(a.collectionViewUrl)?`<a class="store-link" href="${escapeHTML(safeURL(a.collectionViewUrl))}" target="_blank" rel="noopener noreferrer">View on Apple Music ↗</a>`:''}</div><details class="album-audio-options"><summary>Audio options</summary><p class="note">Playback uses your connected source. Lossless audio is matched first.</p><label class="fallback-option"><input type="checkbox" id="album-lossy"> Allow lossy fallback when lossless is unavailable</label></details><div id="album-tracks" aria-live="polite">Loading track list…</div></div>`);images($('#dialog-content'));$('#album-artist-link').onclick=()=>openArtist(a.artistId,a.artistName);$('#album-lossy').checked=window.monoGetLossyFallback?.()||false;$('#album-lossy').onchange=e=>window.monoSetLossyFallback?.(e.target.checked);$('#album-find-sources').disabled=true;const save=$('#save-album');function updateSave(){const exists=saved.some(x=>x.collectionId===id);save.innerHTML='<span class="material-symbols-rounded" aria-hidden="true">'+(exists?'check':'add')+'</span>'+(exists?'Saved':'Save album');save.setAttribute('aria-pressed',exists)}updateSave();save.onclick=()=>{const exists=saved.some(x=>x.collectionId===id);if(exists)saved=saved.filter(x=>x.collectionId!==id);else{if(saved.length>=200)return toast('Your shelf holds 200 albums. Remove one to save another.');saved.push(a)}storeSaved();updateSave();renderAlbums()};try{const rows=await request('lookup',{id:String(id),entity:'song',limit:'200'});if(version!==detailVersion||!$('#album-tracks'))return;const songs=rows.filter(t=>t.wrapperType==='track'&&t.kind==='song');$('#album-tracks').innerHTML=songs.length?songs.map(songRow).join(''):'<p class="note">No track list is available for this album.</p>';$('#album-find-sources').disabled=!songs.length;$('#album-find-sources').onclick=()=>{if(songs[0]){if(window.OktawkaFlow)window.OktawkaFlow.playAlbum(songs.map(t=>toTrack(t,a)),0);else window.monoPlayCatalogTrack?.(toTrack(songs[0],a))}};bindSongs($('#album-tracks'),songs,a)}catch{if(version===detailVersion&&$('#album-tracks'))$('#album-tracks').innerHTML='<p class="note">The track list could not load. You can still save this album.</p>'}}
async function openArtist(id,name='Artist'){const version=++detailVersion;modal(`<div class="eyebrow">ARTIST PROFILE</div><h2>${escapeHTML(name)}</h2><p id="artist-status" class="note" role="status">Loading artist profile…</p><div id="artist-profile-content"></div>`);$('#dialog').classList?.add('artist-profile-dialog');try{if(!Number.isSafeInteger(Number(id))||!id){const matches=await request('search',{term:name,media:'music',entity:'musicArtist',attribute:'artistTerm',limit:'10'});if(version!==detailVersion)return;const match=matches.find(a=>window.MonoMatch.normalize(a.artistName)===window.MonoMatch.normalize(name));if(!match)throw Error('No exact artist profile found. Search Artists to choose the correct artist.');id=match.artistId}id=Number(id);const results=await Promise.allSettled([request('lookup',{id:String(id),entity:'album',limit:'200'}),request('lookup',{id:String(id),entity:'song',limit:'10'})]);if(version!==detailVersion)return;const albumRows=results[0].status==='fulfilled'?results[0].value:[],trackRows=results[1].status==='fulfilled'?results[1].value:[];if(results.every(r=>r.status==='rejected'))throw Error('Artist details could not load. Try again later.');const artist=albumRows.find(r=>r.wrapperType==='artist')||trackRows.find(r=>r.wrapperType==='artist')||knownArtists.get(id)||{artistName:name};knownArtists.set(id,artist);const discography=albumRows.filter(r=>r.collectionType==='Album'&&Number.isSafeInteger(r.collectionId)).filter((a,i,all)=>all.findIndex(b=>b.collectionId===a.collectionId)===i).sort((a,b)=>(b.releaseDate||'').localeCompare(a.releaseDate||''));remember(discography);const top=trackRows.filter(t=>t.wrapperType==='track'&&t.kind==='song');$('#artist-status').textContent=results.some(r=>r.status==='rejected')?'Some artist details could not load.':'Artist catalog · playback depends on matching source availability';$('#artist-profile-content').innerHTML=`<div class="artist-profile-head"><div class="artist-avatar">${escapeHTML(artist.artistName.slice(0,1))}</div><div><div class="eyebrow">ARTIST</div><h2>${escapeHTML(artist.artistName)}</h2><p class="note">${escapeHTML(artist.primaryGenreName||'Music')} · ${discography.length} releases available</p></div></div><h3>Top tracks</h3><p class="note">Apple catalog ordering. Actual play counts are not provided.</p><div id="artist-top-tracks">${top.length?top.map(songRow).join(''):'<p class="note">No top tracks available.</p>'}</div><h3>Discography</h3><p class="note">Albums and singles, newest first.${discography.length>=200?' The catalog limits this response to 200 releases.':''}</p><div class="album-grid artist-discography" id="artist-albums">${discography.length?discography.map(albumCard).join(''):'<p class="note">No releases available.</p>'}</div>`;images($('#artist-profile-content'));bindSongs($('#artist-top-tracks'),top);$('#artist-albums').onclick=e=>{const card=e.target.closest('[data-album]');if(card)openAlbum(Number(card.dataset.album))}}catch(e){if(version===detailVersion)$('#artist-status').textContent=e.message||'Artist profile is unavailable.'}}
$('#catalog-form').onsubmit=e=>{e.preventDefault();searchAlbums($('#catalog-query').value)};$('#catalog-albums').onclick=()=>setMode('albums');$('#catalog-artists').onclick=()=>setMode('artists');document.querySelectorAll('[data-artist]').forEach(b=>b.onclick=()=>searchAlbums(b.dataset.artist));grid.onclick=e=>{const artist=e.target.closest('[data-artist-id]');if(artist){const id=Number(artist.dataset.artistId);openArtist(id,knownArtists.get(id)?.artistName);return}const card=e.target.closest('[data-album]');if(card)openAlbum(Number(card.dataset.album))};$('#saved-albums').onclick=()=>{++searchVersion;mode='albums';$('#album-heading').textContent='Albums to spend time with';$('#catalog-query').placeholder='Search albums or artists';$('#catalog-submit').textContent='Find albums ↗';$('#catalog-albums').setAttribute('aria-pressed',true);$('#catalog-artists').setAttribute('aria-pressed',false);grid.removeAttribute('aria-busy');onlySaved=!onlySaved;renderAlbums();if(!onlySaved)status.textContent=albums.length?`${albums.length} albums · choose an album to play`:'Search an album or artist to explore.'};
const oldSearch=$('#search').oninput;$('#search').oninput=e=>{oldSearch(e);clearTimeout(searchTimer);const term=e.target.value.trim();if(term.length>=2)searchTimer=setTimeout(()=>searchAlbums(term),700)};
window.OktawkaCatalog={request,remember,toTrack};window.monoShowAlbum=openAlbum;window.monoOpenArtist=openArtist;searchAlbums('Daft Punk');
})();
